package main

import "fmt"

// nums is a []int inside the function body.
func sum(nums ...int) int {
	total := 0
	for _, n := range nums { // ranges 0 times when nums is empty
		total += n
	}
	return total
}

func main() {
	fmt.Println(sum(1, 2, 3)) // individual args -> packed into []int{1,2,3}
	fmt.Println(sum())        // no args -> nil slice, len 0, returns 0

	prices := []int{10, 20, 30, 40}
	fmt.Println(sum(prices...)) // spread: pass the existing slice directly

	// Compile error if uncommented (cannot mix individual + spread):
	// fmt.Println(sum(1, prices...))
}

package main

import "fmt"

// double mutates the slice it receives IN PLACE.
func double(nums ...int) {
	for i := range nums {
		nums[i] *= 2 // writes through the shared backing array
	}
}

func main() {
	data := []int{1, 2, 3}
	double(data...)        // spread: double's nums aliases data
	fmt.Println(data)      // caller's slice was mutated!

	// fmt.Println is func Println(a ...any).
	words := []string{"go", "is", "fun"}
	// fmt.Println(words...) // COMPILE ERROR: []string is not []any

	// You must spread a []any, or pass the slice as a single value:
	anys := []any{"go", "is", "fun"}
	fmt.Println(anys...)   // prints: go is fun
	fmt.Println(words)     // prints the slice as one argument: [go is fun]
}
